SELECT device_code, CASE WHEN status_bits >= 13 THEN 'HIGH' ELSE 'LOW' END AS status_bits_tier, BIT_OR(status_bits) AS status_bits_bit_or, MIN(reading_ts) AS first_reading_ts, ROUND(AVG(status_bits), 2) AS avg_status_bits, GROUPING(device_code) AS grouping_id FROM device_readings GROUP BY GROUPING SETS ((device_code, CASE WHEN status_bits >= 13 THEN 'HIGH' ELSE 'LOW' END), (device_code)) ORDER BY avg_status_bits DESC NULLS LAST;
